import Rgb from '../../../src/utils/Rgb';

describe('Rgb.reset', () => {
  let rgbInstance;

  beforeEach(() => {
    rgbInstance = new Rgb(100, 150, 200); // Initialize with non-default values
  });

  test('should reset r, g, and b to 255', () => {
    rgbInstance.reset();
    expect(rgbInstance.r).toBe(255);
    expect(rgbInstance.g).toBe(255);
    expect(rgbInstance.b).toBe(255);
  });

  test('should not throw any errors when called', () => {
    expect(() => rgbInstance.reset()).not.toThrow();
  });

  test('should reset values even if already at default', () => {
    rgbInstance = new Rgb(); // Default values are already 255
    rgbInstance.reset();
    expect(rgbInstance.r).toBe(255);
    expect(rgbInstance.g).toBe(255);
    expect(rgbInstance.b).toBe(255);
  });

  test('should not affect other instances of Rgb', () => {
    const anotherInstance = new Rgb(50, 60, 70);
    rgbInstance.reset();
    expect(anotherInstance.r).toBe(50);
    expect(anotherInstance.g).toBe(60);
    expect(anotherInstance.b).toBe(70);
  });
});

