import Particle from '../../../src/core/Particle';

describe('Particle.removeBehaviour', () => {
  let particle;
  let mockBehaviour1;
  let mockBehaviour2;

  beforeEach(() => {
    particle = new Particle();
    mockBehaviour1 = { parents: [particle] };
    mockBehaviour2 = { parents: [particle] };
    particle.behaviours = [mockBehaviour1, mockBehaviour2];
  });

  test('should remove the specified behaviour from the behaviours array', () => {
    particle.removeBehaviour(mockBehaviour1);
    expect(particle.behaviours).toEqual([mockBehaviour2]);
  });

  test('should set the parents property of the removed behaviour to null', () => {
    particle.removeBehaviour(mockBehaviour1);
    expect(mockBehaviour1.parents).toEqual([]);
  });

  test('should not modify the behaviours array if the behaviour is not found', () => {
    const mockBehaviour3 = { parents: null };
    particle.removeBehaviour(mockBehaviour3);
    expect(particle.behaviours).toEqual([mockBehaviour1, mockBehaviour2]);
  });

  test('should not throw an error if behaviours array is empty', () => {
    particle.behaviours = [];
    expect(() => particle.removeBehaviour(mockBehaviour1)).not.toThrow();
    expect(particle.behaviours).toEqual([]);
  });

  test('should not throw an error if behaviours array is null', () => {
    particle.behaviours = null;
    expect(() => particle.removeBehaviour(mockBehaviour1)).not.toThrow();
    expect(particle.behaviours).toBeNull();
  });

  test('should handle null or undefined behaviour gracefully', () => {
    expect(() => particle.removeBehaviour(null)).not.toThrow();
    expect(() => particle.removeBehaviour(undefined)).not.toThrow();
    expect(particle.behaviours).toEqual([mockBehaviour1, mockBehaviour2]);
  });
});

