describe('Particle.applyBehaviours', () => {
  let particle;

  beforeEach(() => {
    particle = new Particle();
  });

  test('should apply all behaviours correctly', () => {
    const mockBehaviour1 = {
      applyBehaviour: jest.fn(),
    };
    const mockBehaviour2 = {
      applyBehaviour: jest.fn(),
    };

    particle.behaviours = [mockBehaviour1, mockBehaviour2];
    const time = 100;
    const index = 1;

    particle.applyBehaviours(time, index);

    expect(mockBehaviour1.applyBehaviour).toHaveBeenCalledWith(particle, time, index);
    expect(mockBehaviour2.applyBehaviour).toHaveBeenCalledWith(particle, time, index);
  });

  test('should handle behaviours array with null or undefined values', () => {
    const mockBehaviour = {
      applyBehaviour: jest.fn(),
    };

    particle.behaviours = [mockBehaviour, null, undefined];
    const time = 50;
    const index = 2;

    particle.applyBehaviours(time, index);

    expect(mockBehaviour.applyBehaviour).toHaveBeenCalledWith(particle, time, index);
  });

  test('should not throw error if behaviours array is empty', () => {
    particle.behaviours = [];
    const time = 0;
    const index = 0;

    expect(() => particle.applyBehaviours(time, index)).not.toThrow();
  });

  test('should throw TypeError if a behaviour does not have applyBehaviour method', () => {
    const invalidBehaviour = {};
    particle.behaviours = [invalidBehaviour];
    const time = 10;
    const index = 3;

    expect(() => particle.applyBehaviours(time, index)).toThrow(TypeError);
  });

  test('should not modify behaviours array', () => {
    const mockBehaviour = {
      applyBehaviour: jest.fn(),
    };

    particle.behaviours = [mockBehaviour];
    const originalBehaviours = [...particle.behaviours];
    const time = 20;
    const index = 4;

    particle.applyBehaviours(time, index);

    expect(particle.behaviours).toEqual(originalBehaviours);
  });
});

