describe('Particle.destroy', () => {
  let particle;

  beforeEach(() => {
    particle = new Particle();
    particle.energy = 100;
    particle.dead = false;
    particle.parent = { someParent: true };
    particle.behaviours = ['behaviour1', 'behaviour2'];
    particle.removeAllBehaviours = jest.fn();
  });

  it('should set energy to 0', () => {
    particle.destroy();
    expect(particle.energy).toBe(0);
  });

  it('should mark the particle as dead', () => {
    particle.destroy();
    expect(particle.dead).toBe(true);
  });

  it('should nullify the parent reference', () => {
    particle.destroy();
    expect(particle.parent).toBeNull();
  });

  it('should remove all behaviours', () => {
    particle.destroy();
    expect(particle.removeAllBehaviours).toHaveBeenCalled();
  });

  it('should not modify other properties', () => {
    const initialId = particle.id;
    const initialP = particle.p;
    const initialRgb = particle.rgb;

    particle.destroy();

    expect(particle.id).toBe(initialId);
    expect(particle.p).toBe(initialP);
    expect(particle.rgb).toBe(initialRgb);
  });
});

