    particle.life = 100;
    particle.age = 50;
    particle.dead = true;

    particle.reset();

    expect(particle.life).toBeUndefined();
    expect(particle.age).toBeUndefined();
    expect(particle.dead).toBe(false);
  });

  test('should reset position, velocity, and acceleration vectors to default values', () => {
    particle.p.set(10, 20);
    particle.v.set(5, 15);
    particle.a.set(2, 8);

    particle.reset();

    expect(particle.p.x).toBe(0);
    expect(particle.p.y).toBe(0);
    expect(particle.v.x).toBe(0);
    expect(particle.v.y).toBe(0);
    expect(particle.a.x).toBe(0);
    expect(particle.a.y).toBe(0);
  });

  test('should reset old position, velocity, and acceleration vectors to default values', () => {
    particle.old.p.set(30, 40);
    particle.old.v.set(25, 35);
    particle.old.a.set(12, 18);

    particle.reset();

    expect(particle.old.p.x).toBe(0);
    expect(particle.old.p.y).toBe(0);
    expect(particle.old.v.x).toBe(0);
    expect(particle.old.v.y).toBe(0);
    expect(particle.old.a.x).toBe(0);
    expect(particle.old.a.y).toBe(0);
  });

  test('should clear behaviours array', () => {
    particle.behaviours = ['behaviour1', 'behaviour2'];

    particle.reset();

    expect(particle.behaviours).toEqual([]);
  });

  test('should reset rgb to default values', () => {
    particle.rgb.set(255, 255, 255);

    particle.reset();

    expect(particle.rgb.r).toBe(0);
    expect(particle.rgb.g).toBe(0);
    expect(particle.rgb.b).toBe(0);
  });

  test('should return the Particle instance for method chaining', () => {
    const result = particle.reset();

    expect(result).toBe(particle);
  });
});

