    expect(rectangle.contains(70, 30)).toBe(false); // Point (70, 30) is outside
  });

  test('should return false for a point outside the rectangle (above)', () => {
    expect(rectangle.contains(20, 10)).toBe(false); // Point (20, 10) is outside
  });

  test('should return false for a point outside the rectangle (below)', () => {
    expect(rectangle.contains(20, 60)).toBe(false); // Point (20, 60) is outside
  });

