  });

  test('should handle rectangles with negative dimensions (invalid case)', () => {
    const invalidRectangle = new Rectangle(10, 20, -50, -30);
    expect(invalidRectangle.contains(10, 20)).toBe(false); // Invalid rectangle, point is not inside
  });
});

