describe('Stats.destroy', () => {
  let stats;
  let mockProton;
  let mockContainer;

  beforeEach(() => {
    // Mock the proton object
    mockProton = { someProperty: 'value' };

    // Create a mock container element
    mockContainer = document.createElement('div');
    document.body.appendChild(mockContainer);

    // Initialize the Stats instance
    stats = new Stats(mockProton);
    stats.container = mockContainer;
  });

  afterEach(() => {
    // Clean up the DOM
    if (mockContainer.parentNode) {
      mockContainer.parentNode.removeChild(mockContainer);
    }
    stats = null;
  });

  it('should remove the container from the DOM if it exists', () => {
    // Ensure the container is in the DOM before calling destroy
    expect(document.body.contains(stats.container)).toBe(true);

    // Call the destroy method
    stats.destroy();

    // Verify the container is removed from the DOM
    expect(document.body.contains(stats.container)).toBe(false);
  });

  it('should set the container property to null', () => {
    // Call the destroy method
    stats.destroy();

    // Verify the container property is null
    expect(stats.container).toBeNull();
  });

  it('should set the proton property to null', () => {
    // Call the destroy method
    stats.destroy();

    // Verify the proton property is null
    expect(stats.proton).toBeNull();
  });

  it('should handle the absence of a container gracefully', () => {
    // Remove the container and set it to null
    stats.container = null;

    // Call the destroy method
    stats.destroy();

    // Verify no errors occurred and properties are null
    expect(stats.container).toBeNull();
    expect(stats.proton).toBeNull();
  });
});

