    const mockListener1 = jest.fn(() => false);
    const mockListener2 = jest.fn(() => true);
    dispatcher._listeners['testEvent'] = [mockListener1, mockListener2];

    const result = dispatcher.dispatchEvent('testEvent', {});

    expect(result).toBe(true);
  });

