import CircleZone from '../../../src/zone/CircleZone';

describe('CircleZone - crossing', () => {
  let circleZone;
  let mockParticle;

  beforeEach(() => {
    circleZone = new CircleZone(0, 0, 10);
    mockParticle = {
      p: {
        distanceTo: jest.fn(),
        x: 5,
        y: 5,
      },
      radius: 1,
      dead: false,
    };
  });

  test('should set particle.dead to true if crossing type is "dead" and particle exceeds radius', () => {
    circleZone.crossType = 'dead';
    mockParticle.p.distanceTo.mockReturnValue(12); // Particle is outside the circle

    circleZone.crossing(mockParticle);

    expect(mockParticle.dead).toBe(true);
  });

  test('should not set particle.dead if crossing type is "dead" and particle is within radius', () => {
    circleZone.crossType = 'dead';
    mockParticle.p.distanceTo.mockReturnValue(8); // Particle is inside the circle

    circleZone.crossing(mockParticle);

    expect(mockParticle.dead).toBe(false);
  });

  test('should perform symmetric transformation if crossing type is "bound" and particle intersects the circle', () => {
    circleZone.crossType = 'bound';
    mockParticle.p.distanceTo.mockReturnValue(10); // Particle is on the boundary
    const originalX = mockParticle.p.x;
    const originalY = mockParticle.p.y;

    // Mock the symmetric transformation logic
    circleZone.symmetricTransform = jest.fn((particle) => {
      particle.p.x = -particle.p.x;
      particle.p.y = -particle.p.y;
    });

    circleZone.crossing(mockParticle);

    expect(circleZone.symmetricTransform).toHaveBeenCalledWith(mockParticle);
    expect(mockParticle.p.x).toBe(-originalX);
    expect(mockParticle.p.y).toBe(-originalY);
  });

  test('should not modify particle if crossing type is "bound" and particle is within radius', () => {
    circleZone.crossType = 'bound';
    mockParticle.p.distanceTo.mockReturnValue(5); // Particle is inside the circle
    const originalX = mockParticle.p.x;
    const originalY = mockParticle.p.y;

    circleZone.crossing(mockParticle);

    expect(mockParticle.p.x).toBe(originalX);
    expect(mockParticle.p.y).toBe(originalY);
  });

  test('should set alert to false if crossing type is "cross"', () => {
    circleZone.crossType = 'cross';
    circleZone.alert = true;

    circleZone.crossing(mockParticle);

    expect(circleZone.alert).toBe(false);
