      data: {
        alphaA: 0.0005,
        alphaB: 0.0005,
      },
      alpha: 0,
      energy: 0.5,
    };
    const time = 50;
    const index = 1;

    alphaInstance.applyBehaviour(particle, time, index);

    expect(particle.alpha).not.toBeNaN();
    expect(particle.alpha).toBe(0);
  });

