    const initializer1 = { name: 'init1' };
    const initializer2 = { name: 'init2' };
    const nonExistentInitializer = { name: 'nonExistent' };
    emitter.initializes = [initializer1, initializer2];

    emitter.removeInitialize(nonExistentInitializer);

    expect(emitter.initializes).toEqual([initializer1, initializer2]);
  });

  test('should handle empty initializes array gracefully', () => {
    const initializer = { name: 'init1' };
    emitter.initializes = [];

    emitter.removeInitialize(initializer);

    expect(emitter.initializes).toEqual([]);
  });

  test('should not throw an error if initializer is null or undefined', () => {
    emitter.initializes = [{ name: 'init1' }];

    expect(() => emitter.removeInitialize(null)).not.toThrow();
    expect(() => emitter.removeInitialize(undefined)).not.toThrow();
    expect(emitter.initializes).toEqual([{ name: 'init1' }]);
  });

