import Proton from '../../../src/core/Proton';

describe('Proton.removeEmitter', () => {
  let proton;
  let mockEmitter;

  beforeEach(() => {
    proton = new Proton();
    mockEmitter = { parent: proton };
    proton.emitters.push(mockEmitter);
  });

  test('should remove the emitter from the emitters array', () => {
    expect(proton.emitters).toContain(mockEmitter);

    proton.removeEmitter(mockEmitter);

    expect(proton.emitters).not.toContain(mockEmitter);
  });

  test('should set the emitter\'s parent property to null', () => {
    expect(mockEmitter.parent).toBe(proton);

    proton.removeEmitter(mockEmitter);

    expect(mockEmitter.parent).toBeNull();
  });

  test('should dispatch an event indicating the emitter has been removed', () => {
    const dispatchEventSpy = jest.spyOn(proton, 'dispatchEvent');

    proton.removeEmitter(mockEmitter);

    expect(dispatchEventSpy).toHaveBeenCalledWith(Proton.EMITTER_REMOVED, mockEmitter);
  });

  test('should not throw an error if the emitter is not found in the emitters array', () => {
    const nonExistentEmitter = { parent: null };

    expect(() => proton.removeEmitter(nonExistentEmitter)).not.toThrow();
  });

  test('should not modify emitters array if emitter is not found', () => {
    const initialEmitters = [...proton.emitters];
    const nonExistentEmitter = { parent: null };

    proton.removeEmitter(nonExistentEmitter);

    expect(proton.emitters.length).toEqual(initialEmitters.length);
    expect(proton.emitters).toEqual(initialEmitters);
  });
});

