import Pool from '../../../src/core/Pool';

describe('Pool.destroy', () => {
  let pool;

  beforeEach(() => {
    pool = new Pool(10);
    pool.cache = {
      item1: [1, 2, 3],
      item2: [4, 5, 6],
      item3: [7, 8, 9],
    };
    pool.total = Object.values(pool.cache).reduce((sum, arr) => sum + arr.length, 0);
  });

  test('should clear all cached items and reset the cache object', () => {
    pool.destroy();

    expect(pool.cache).toEqual({});
  });

  test('should reset the total count to 0', () => {
    pool.destroy();

    expect(pool.total).toBe(0);
  });

  test('should set the length of each cached item to 0 before deletion', () => {
    const mockCache = {
      item1: [1, 2, 3],
      item2: [4, 5],
    };
    pool.cache = mockCache;

    pool.destroy();

    Object.keys(mockCache).forEach((key) => {
      expect(pool.cache[key]).toBeUndefined();
    });
  });

  test('should handle empty cache gracefully', () => {
    pool.cache = {};
    pool.total = 0;

    pool.destroy();

    expect(pool.cache).toEqual({});
    expect(pool.total).toBe(0);
  });
});

