import Pool from '../../../src/core/Pool';

describe('Pool.expire', () => {
  let pool;

  beforeEach(() => {
    pool = new Pool(10);
  });

  test('should add target to the cache associated with its __puid', () => {
    const target = { __puid: 'unique-id-1' };
    pool.cache[target.__puid] = [];

    const result = pool.expire(target);

    expect(result).toEqual([target]);
    expect(pool.cache[target.__puid]).toEqual([target]);
  });

  test('should create a new cache if none exists for the target __puid', () => {
    const target = { __puid: 'unique-id-2' };

    const result = pool.expire(target);

    expect(result).toEqual([target]);
    expect(pool.cache[target.__puid]).toEqual([target]);
    expect(Array.isArray(pool.cache[target.__puid])).toBe(true);
  });

  test('should throw TypeError if target is null', () => {
    expect(() => pool.expire(null)).toThrow(TypeError);
  });

  test('should throw TypeError if target is undefined', () => {
    expect(() => pool.expire(undefined)).toThrow(TypeError);
  });

  test('should throw TypeError if target does not have __puid property', () => {
    const target = {};
    expect(() => pool.expire(target)).toThrow(TypeError);
  });

  test('should not alter the target object itself', () => {
    const target = { __puid: 'unique-id-3', data: 'test' };
    pool.cache[target.__puid] = [];

    pool.expire(target);

    expect(target).toEqual({ __puid: 'unique-id-3', data: 'test' });
  });
});

